    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Locate exceptional center cells in the repeated tiles. An exceptional
    # color extends along its tile row and column, but only into zero gutters.
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                counts[v] = counts.get(v, 0) + 1
    if not counts:
        return out
    background = max(counts, key=counts.get)
    base_color = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and grid[r][c] != background:
                base_color = grid[r][c]
